	/**
	 * Default Constructor
	 */
    public ClinicianService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ClinicianEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ClinicianRepository.class) );
		this.validator		= applicationContext.getBean(ClinicianValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Clinician
	 */
		public Clinician createClinician( CreateClinicianCommand command ) {

		Clinician entity = new Clinician();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setClinicianId( command.getClinicianId() );
            entity.setFirstName( command.getFirstName() );
            entity.setLastName( command.getLastName() );
            entity.setLicenseNumber( command.getLicenseNumber() );
            entity.setClinicianType( command.getClinicianType() );
            entity.setSpecialty( command.getSpecialty() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Clinician {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateClinicianCommand
	 * @return		Clinician
	 */
	public Clinician updateClinician( UpdateClinicianCommand command ) {

		Clinician entity = new Clinician();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setClinicianId( command.getClinicianId() );
            entity.setFirstName( command.getFirstName() );
            entity.setLastName( command.getLastName() );
            entity.setLicenseNumber( command.getLicenseNumber() );
            entity.setCareTeams( command.getCareTeams() );
            entity.setAppointments( command.getAppointments() );
            entity.setEncounters( command.getEncounters() );
            entity.setProcedures( command.getProcedures() );
            entity.setImagingReports( command.getImagingReports() );
            entity.setClinicianType( command.getClinicianType() );
            entity.setSpecialty( command.getSpecialty() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Clinician {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteClinicianCommand
	 */
	public void delete( DeleteClinicianCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getClinicianId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Clinician {0} ", id );

	}

	/**
	 * Method to retrieve the Clinician via ClinicianFetchOneSummary
	 * @param 	summary ClinicianFetchOneSummary
	 * @return 	ClinicianFetchOneResponse
	 */
	public Clinician getClinician( ClinicianFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ClinicianFetchOneSummary arg cannot be null" );

		Clinician entity = null;
		UUID id = summary.getClinicianId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Clinician using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Clinicians
	 *
	 * @return 	List<Clinician>
	 */
    public List<Clinician> getAllClinician() {
		List<Clinician> list = projector.findAll( new FindAllClinicianQuery() );
		return list;
	}


